using System.Runtime.InteropServices;using Essco.Application.Configuration;using Essco.Application.Customers;using Essco.Application.Returns;using Essco.Domain.Returns;using Microsoft.Extensions.Options;
namespace Essco.SapBridge.Worker;public sealed class ComSapReturnGateway(IOptions<EsscoOptions> options,ILogger<ComSapReturnGateway> logger):ISapReturnGateway
{public ValueTask<SapProcessingResult>CreateCreditNoteAsync(ReturnRequest request,CancellationToken token){token.ThrowIfCancellationRequested();if(!options.Value.Sap.Enabled)return ValueTask.FromResult(new SapProcessingResult(false,null,"La conexión SAP no está habilitada.",false));var done=new TaskCompletionSource<SapProcessingResult>(TaskCreationOptions.RunContinuationsAsynchronously);var thread=new Thread(()=>{try{done.TrySetResult(Create(request));}catch(COMException ex){logger.LogWarning("Error COM SAP {Code} procesando devolución {Return}",ex.ErrorCode,request.Number);done.TrySetResult(new(false,null,$"Error COM SAP ({ex.ErrorCode}).",true));}catch(Exception ex){logger.LogError(ex,"Error procesando devolución {Return}",request.Number);done.TrySetResult(new(false,null,"Error interno del adaptador SAP.",true));}}){IsBackground=true,Name="Essco SAP DI API Return"};thread.SetApartmentState(ApartmentState.STA);thread.Start();return new(done.Task);}
 private SapProcessingResult Create(ReturnRequest x){dynamic? company=null;dynamic? note=null;try{var type=Type.GetTypeFromProgID("SAPbobsCOM.Company")??throw new COMException("SAP DI API no está registrada.");company=Activator.CreateInstance(type)??throw new COMException("No fue posible crear Company.");var c=options.Value.Sap;company.Server=c.Server;company.CompanyDB=c.CompanyDatabase;company.UserName=c.UserName;company.Password=c.Password;company.DbUserName=c.DatabaseUserName;company.DbPassword=c.DatabasePassword;company.LicenseServer=c.LicenseServer;company.DbServerType=c.DatabaseServerType;company.UseTrusted=false;var connected=(int)company.Connect();if(connected!=0)return Failure(company,connected,true);note=company.GetBusinessObject(19);note.CardCode=x.CustomerCode;note.DocDueDate=x.Date.ToDateTime(TimeOnly.MinValue);note.Comments=$"Devolución Essco {x.Number}: {x.Comments}";note.NumAtCard=x.Number.ToString(System.Globalization.CultureInfo.InvariantCulture);for(var i=0;i<x.Lines.Count;i++){var line=x.Lines.ElementAt(i);if(i>0)note.Lines.Add();note.Lines.ItemCode=line.ItemCode;note.Lines.Quantity=(double)line.Quantity;note.Lines.Currency=c.DepositCurrency;note.Lines.Price=(double)line.Price;note.Lines.WarehouseCode=line.Warehouse;note.Lines.FreeText=line.Reason;SetField(note.Lines,"U_DescFijo",(double)line.FixedDiscount);if(line.PromotionalDiscount>=100){SetField(note.Lines,"U_DescProm",0);note.Lines.DiscountPercent=0;note.Lines.TaxOnly=1;}else{SetField(note.Lines,"U_DescProm",(double)line.PromotionalDiscount);note.Lines.DiscountPercent=(double)line.PromotionalDiscount;note.Lines.TaxOnly=0;}}var added=(int)note.Add();if(added!=0)return Failure(company,added,false);var key=Convert.ToString(company.GetNewObjectKey())??"";return new(true,key,null,false);}finally{Release(note);try{if(company is not null&&(bool)company.Connected)company.Disconnect();}catch(COMException){}Release(company);}}
 private static void SetField(dynamic x,string n,object v)=>x.UserFields.Fields.Item(n).Value=v;private static SapProcessingResult Failure(dynamic c,int code,bool retry){string m="";try{c.GetLastError(out code,out m);}catch(COMException){}return new(false,null,$"SAP rechazó la operación ({code}): {m}",retry);}private static void Release(object? x){if(x is not null&&Marshal.IsComObject(x))Marshal.FinalReleaseComObject(x);}}
